--- FILE: /Users/wrr/work/ai-agent-v2/src/tool/grep.ts ---
Range: 1 - 125

1 | import { search, type SearchMatch,validatePattern } from '@mcpc-tech/ripgrep-napi';
2 | import { z } from 'zod';
3 | import { BaseTool, ToolOutput } from './base';
4 | 
5 | const schema = z.object({
6 |   pattern: z.string().describe('The regex pattern to search for in file contents'),
7 |   filePattern: z.string().nullable().describe('Glob pattern, e.g. *.ts'),
8 | });
9 | 
10 | export default class GrepTool extends BaseTool<typeof schema> {
11 |   name = 'grep';
12 | 
13 |   description = `- Fast content search tool that works with any codebase size
14 | - Searches file contents using regular expressions
15 | - Supports full regex syntax (eg. "log.*Error", "function\\s+\\w+", etc.)
16 | - Filter files by pattern with the include parameter (eg. "*.js", "*.{ts,tsx}")
17 | - Returns file paths and line numbers with at least one match sorted by modification time
18 | - Use this tool when you need to find files containing specific patterns
19 | - If you need to identify/count the number of matches within files, use the Bash tool with 'rg' (ripgrep) directly. Do NOT use 'grep'.
20 | - When you are doing an open-ended search that may require multiple rounds of globbing and grepping, use the Task tool instead
21 | `;
22 |   schema = schema;
23 | 
24 |   async execute({ pattern, filePattern }: any): Promise<ToolOutput> {
25 |     // 基础排除规则（始终生效）
26 |     const ignorePatterns = [
27 |       '**/node_modules/**',
28 |       '**/dist/**',
29 |       '**/.git/**',
30 |       '**/*.min.js',
31 |       '**/*.min.css',
32 |       '**/coverage/**',
33 |       '**/.next/**',
34 |       '**/.nuxt/**',
35 |       '**/build/**',
36 |     ];
37 | 
38 |     // 构建搜索选项
39 |     const options = {
40 |       caseSensitive: false,  // 智能大小写匹配
41 |       ignorePatterns,
42 |       // 如果指定了文件模式，添加 glob 过滤
43 |       // 注意：ripgrep-napi 没有直接的 glob 支持，需要通过 ignorePatterns 实现
44 |     };
45 | 
46 |     try {
47 |       if (!validatePattern(pattern)) {
48 |         return {
49 |           metadata: {
50 |             error: 'Invalid pattern format',
51 |              ok: false,
52 | 
53 |           },
54 |           output: 'Invalid pattern format',
55 |         };
56 |       }
57 |       
58 |       // 使用 ripgrep-napi 进行搜索
59 |       const result = search(pattern, ['.'], options);
60 | 
61 |       // 如果搜索失败
62 |       if (!result.success) {
63 |         return {
64 |           metadata: {
65 |             error: result.error || 'Unknown error',
66 |              ok: false,
67 |           },
68 |           output: result.error || 'Unknown error',
69 |         };
70 |       }
71 | 
72 |       // 过滤结果（如果指定了 filePattern）
73 |       let matches = result.matches;
74 |       if (filePattern) {
75 |         // 将 glob 模式转换为正则表达式进行过滤
76 |         const globRegex = new RegExp(
77 |           filePattern
78 |             .replace(/\*/g, '.*')
79 |             .replace(/\?/g, '.')
80 |             .replace(/\./g, '\\.')
81 |         );
82 |         matches = matches.filter(m => globRegex.test(m.path));
83 |       }
84 | 
85 |       // 限制返回数量，防止 Token 爆炸
86 |       const preview = matches.slice(0, 200);
87 |       const formatted = preview.map((m: SearchMatch) => ({
88 |         file: m.path,
89 |         line: m.lineNumber,
90 |         content: m.line.trim(),
91 |       }));
92 | 
93 |       if(!preview?.length) {
94 |         return {
95 |           metadata: {
96 |             count: 0,
97 |             msg: 'No matches found',
98 |             ok: true,
99 |           },
100 |           output: 'No matches found',
101 |         };
102 |       }
103 |       
104 | 
105 |       return {
106 |         metadata: {
107 |           count: preview.length,
108 |           ok: true,
109 |           reuslt:formatted
110 |         },
111 |         output: JSON.stringify(formatted, null, 2),
112 |       };
113 |       
114 |     } catch (error: any) {
115 |       return {
116 |         metadata: {
117 |           error: error?.message || String(error),
118 |           ok: false,
119 |         },
120 |         output: error?.message || String(error),
121 |       };
122 |     }
123 |   }
124 | }
